$ErrorActionPreference = "Stop"

$root = (Get-Location).Path
$ws = Join-Path $root "runtime\workspaces\ahos-autopilot"
$pkg = Join-Path $ws "ahos_core"
$auditPath = Join-Path $pkg "ahos\audit.py"
$testPath = Join-Path $pkg "tests\test_audit.py"
$backlogPath = Join-Path $pkg "AHOS_BACKLOG.json"
$python = Join-Path $root ".venv\Scripts\python.exe"

if (-not (Test-Path $auditPath)) { throw "audit.py not found: $auditPath" }
if (-not (Test-Path $backlogPath)) { throw "backlog not found: $backlogPath" }
if (-not (Test-Path $python)) { throw "Python venv not found: $python" }

Copy-Item $auditPath "$auditPath.bak" -Force
if (Test-Path $testPath) { Copy-Item $testPath "$testPath.bak" -Force }

[IO.File]::WriteAllBytes($auditPath, [Convert]::FromBase64String(""))
[IO.File]::WriteAllBytes($testPath, [Convert]::FromBase64String(""))

Write-Host "=== AHOS-008 LOCAL IMPLEMENTATION ==="
Write-Host "audit.py + test_audit.py written."
Write-Host "Running full AHOS test suite (NO OpenAI API calls)..."

$oldPythonPath = $env:PYTHONPATH
Push-Location $pkg
try {
    $env:PYTHONPATH = $pkg
    & $python -m pytest -q
    $testExit = $LASTEXITCODE
} finally {
    Pop-Location
    $env:PYTHONPATH = $oldPythonPath
}

if ($testExit -ne 0) {
    Write-Host "Tests failed. Restoring previous files..."
    Copy-Item "$auditPath.bak" $auditPath -Force
    if (Test-Path "$testPath.bak") {
        Copy-Item "$testPath.bak" $testPath -Force
    } else {
        Remove-Item $testPath -Force -ErrorAction SilentlyContinue
    }
    throw "AHOS-008 tests failed; changes restored."
}

Remove-Item "$auditPath.bak" -Force -ErrorAction SilentlyContinue
Remove-Item "$testPath.bak" -Force -ErrorAction SilentlyContinue

$b = Get-Content $backlogPath -Raw | ConvertFrom-Json
$t = $b.tasks | Where-Object { $_.id -eq "AHOS-008" } | Select-Object -First 1
if (-not $t) { throw "AHOS-008 not found in backlog." }
$t.status = "completed"
if ($t.PSObject.Properties.Name -contains "completed_at") {
    $t.completed_at = [DateTime]::UtcNow.ToString("o")
} else {
    $t | Add-Member -NotePropertyName completed_at -NotePropertyValue ([DateTime]::UtcNow.ToString("o"))
}
$json = $b | ConvertTo-Json -Depth 12
[IO.File]::WriteAllText($backlogPath, $json, (New-Object System.Text.UTF8Encoding($false)))

git -C $ws add ahos_core/ahos/audit.py ahos_core/tests/test_audit.py ahos_core/AHOS_BACKLOG.json
git -C $ws -c user.name="Miniverse Autopilot" -c user.email="miniverse@local.invalid" commit -m "feat(ahos): add tamper-evident audit journal"
if ($LASTEXITCODE -ne 0) { throw "git commit failed." }

git -C $ws push origin HEAD
if ($LASTEXITCODE -ne 0) { throw "git push failed." }

Write-Host ""
Write-Host "=== AHOS-008 COMPLETE ==="
Write-Host "Full AHOS tests: PASS"
Write-Host "Backlog: AHOS-008 -> completed"
Write-Host "Git push: PASS"
Write-Host "OpenAI API calls: 0"
